/* 학습 해설
 * Sysfs chip 이름: 잠금과 빈 출력
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * descriptor raw spinlock_irq 안에서 chip과 chip name이 모두 있으면 bounded 문자열과 newline을 출력합니다. 없으면 ret 0으로 빈 출력입니다. kobject→descriptor 관계를 container_of로 되찾고 필드 관찰을 잠금 범위에 넣습니다. 출력 pointer 수명은 sysfs/kobject 계약과 연결됩니다.
 * chip NULL·name NULL·유효 세 경우를 풉니다. 이름을 새로 할당하는 작업이 아니라 보유한 이름을 읽는 작업임을 표시합니다.
 */
static ssize_t chip_name_show(struct kobject *kobj,
			      struct kobj_attribute *attr, char *buf)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);
	ssize_t ret = 0;

	raw_spin_lock_irq(&desc->lock);
	if (desc->irq_data.chip && desc->irq_data.chip->name) {
		ret = scnprintf(buf, PAGE_SIZE, "%s\n",
				desc->irq_data.chip->name);
	}
	raw_spin_unlock_irq(&desc->lock);

	return ret;
}
IRQ_ATTR_RO(chip_name);

static ssize_t hwirq_show(struct kobject *kobj,
