		ret = sprintf(buf, "%lu\n", desc->irq_data.hwirq);

/* 학습 해설
 * Sysfs hwirq: domain 조건의 번호
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * descriptor lock 안에서 domain이 있을 때만 irq_data.hwirq를 unsigned long 문자열로 출력합니다. domain이 없으면 빈 결과입니다. hardware 번호와 Linux logical IRQ 번호는 다를 수 있으므로 sysfs 이름을 보고 동일한 번호라고 가정하지 않습니다. caller buffer는 sysfs page 계약입니다.
 * domain mapping에서 hwirq 7→logical 42 예를 그립니다. 출력 field와 descriptor 번호를 구별하고 domain 없는 경우의 빈 반환을 읽습니다.
 */
static ssize_t hwirq_show(struct kobject *kobj,
			  struct kobj_attribute *attr, char *buf)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);
	ssize_t ret = 0;

	raw_spin_lock_irq(&desc->lock);
	if (desc->irq_data.domain)
		ret = sprintf(buf, "%lu\n", desc->irq_data.hwirq);
	raw_spin_unlock_irq(&desc->lock);

	return ret;
}
IRQ_ATTR_RO(hwirq);

