/* 학습 해설
 * Sysfs action 목록: 잠금 안의 순회
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * descriptor lock 안에서 action 이름을 쉼표로 bounded 출력합니다. 목록 출력이 있으면 unlock 뒤 newline을 추가하고 비어 있으면 길이 0입니다. IRQ_ATTR_RO와 irq_attrs는 읽기 전용 show 속성을 연결하며 배열 끝의 NULL이 종료 sentinel입니다. 목록 순회와 등록·해제의 잠금 계약을 함께 읽습니다.
 * action 이름 A·B의 A,B 출력을 써봅니다. attribute 등록 배열의 일곱 속성과 NULL 끝을 확인하고 쓰기 handler가 있는 것으로 가정하지 않습니다.
 */
static ssize_t actions_show(struct kobject *kobj,
			    struct kobj_attribute *attr, char *buf)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);
	struct irqaction *action;
	ssize_t ret = 0;
	char *p = "";

	raw_spin_lock_irq(&desc->lock);
	for_each_action_of_desc(desc, action) {
		ret += scnprintf(buf + ret, PAGE_SIZE - ret, "%s%s",
				 p, action->name);
		p = ",";
	}
	raw_spin_unlock_irq(&desc->lock);

	if (ret)
		ret += scnprintf(buf + ret, PAGE_SIZE - ret, "\n");

	return ret;
}
IRQ_ATTR_RO(actions);

static struct attribute *irq_attrs[] = {
	&per_cpu_count_attr.attr,
	&chip_name_attr.attr,

/* 학습 해설
 * IRQ sysfs 추가: 비핵심 실패와 표시
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * base kobject가 준비됐을 때 descriptor kobject를 번호 이름으로 추가합니다. 실패는 경고하고 계속하며 성공에만 IRQS_SYSFS를 세웁니다. 늦은 초기화의 실패는 rollback할 수 없고 핵심 IRQ 기능이 아니란 주석입니다. SYSFS off 대체는 빈 함수입니다.
 * base 없는 early boot·추가 실패·성공 세 경우를 그립니다. IRQ 할당 성공과 sysfs 노출 성공을 별개로 읽고 표시 bit가 성공을 추적하는 이유를 설명합니다.
 */
static void irq_sysfs_add(int irq, struct irq_desc *desc)
{
	if (irq_kobj_base) {
		/*
		 * Continue even in case of failure as this is nothing
		 * crucial and failures in the late irq_sysfs_init()
		 * cannot be rolled back.
		 */
		if (kobject_add(&desc->kobj, irq_kobj_base, "%d", irq))
			pr_warn("Failed to add kobject for irq %d\n", irq);
		else
			desc->istate |= IRQS_SYSFS;
	}
}

static void irq_sysfs_del(struct irq_desc *desc)
{
	/*
	 * Only invoke kobject_del() when kobject_add() was successfully
	 * invoked for the descriptor. This covers both early boot, where
	 * sysfs is not initialized yet, and the case of a failed
	 * kobject_add() invocation.
	 */
	if (desc->istate & IRQS_SYSFS)
		kobject_del(&desc->kobj);
}

/* 학습 해설
 * IRQ sysfs 삭제: 등록 성공의 조건
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * IRQS_SYSFS 표시가 있을 때만 kobject_del합니다. early boot에서 등록하지 않았거나 add 실패한 descriptor를 잘못 삭제하지 않는 guard입니다. kobject_del은 노출 제거이고 최종 객체 수명 종료는 put/release와 구분합니다. SYSFS off 구현은 빈 함수입니다.
 * 등록 여부 bit 0·1의 호출을 풉니다. sysfs 제거·tree 삭제·RCU callback·kobject release의 다른 시점을 한 수명 그림으로 연결합니다.
 */
static void irq_sysfs_del(struct irq_desc *desc)
{
	/*
	 * Only invoke kobject_del() when kobject_add() was successfully
	 * invoked for the descriptor. This covers both early boot, where
	 * sysfs is not initialized yet, and the case of a failed
	 * kobject_add() invocation.
	 */
	if (desc->istate & IRQS_SYSFS)
		kobject_del(&desc->kobj);
}

static int __init irq_sysfs_init(void)
{
	struct irq_desc *desc;
	int irq;

	/* Prevent concurrent irq alloc/free */
	irq_lock_sparse();

	irq_kobj_base = kobject_create_and_add("irq", kernel_kobj);
	if (!irq_kobj_base) {
		irq_unlock_sparse();
		return -ENOMEM;
	}

/* 학습 해설
 * IRQ sysfs 초기화: sparse 할당과 직렬화
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * sparse lock으로 alloc/free를 막고 kernel 아래 irq base를 생성합니다. 실패면 unlock하고 ENOMEM입니다. 성공이면 이미 있는 descriptor 모두에 sysfs_add를 수행하고 unlock 후 0입니다. postcore_initcall에 연결되며 개별 add 실패는 전체 오류로 누적하지 않습니다.
 * early IRQ 할당과 늦은 sysfs 준비를 두 단계로 그립니다. base 생성 오류와 개별 add 경고의 다른 처리 정책을 비교합니다.
 */
static int __init irq_sysfs_init(void)
{
	struct irq_desc *desc;
	int irq;

	/* Prevent concurrent irq alloc/free */
	irq_lock_sparse();

	irq_kobj_base = kobject_create_and_add("irq", kernel_kobj);
	if (!irq_kobj_base) {
		irq_unlock_sparse();
		return -ENOMEM;
	}

	/* Add the already allocated interrupts */
	for_each_irq_desc(irq, desc)
		irq_sysfs_add(irq, desc);
	irq_unlock_sparse();

	return 0;
}
postcore_initcall(irq_sysfs_init);

#else /* !CONFIG_SYSFS */

static const struct kobj_type irq_kobj_type = {

/* 학습 해설
 * Sparse IRQ 조회: Maple Tree pointer
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SPARSE 구성은 mtree_load로 logical IRQ 번호에 연결된 descriptor pointer를 조회합니다. 객체 할당이나 명시적인 RCU read lock은 이 본문에 없습니다. tree 자체 조회 지원과 반환 pointer를 계속 사용하는 동안의 수명 보호는 구별해야 합니다. 호출 문맥의 mutex·RCU·IRQ 등록 계약을 확인합니다.
 * tree 번호→객체 pointer의 연결을 그립니다. kstat_irqs_usr의 RCU 범위와 비교하고 조회한 객체를 임의 free하거나 무기한 유지하지 않습니다.
 */
struct irq_desc *irq_to_desc(unsigned int irq)
{
	return mtree_load(&sparse_irqs, irq);
}
#ifdef CONFIG_KVM_BOOK3S_64_HV_MODULE
EXPORT_SYMBOL_GPL(irq_to_desc);
#endif

void irq_lock_sparse(void)
{
	mutex_lock(&sparse_irq_lock);
}

void irq_unlock_sparse(void)
{
	mutex_unlock(&sparse_irq_lock);
}

static struct irq_desc *alloc_desc(int irq, int node, unsigned int flags,
				   const struct cpumask *affinity,
				   struct module *owner)
{
	struct irq_desc *desc;
	int ret;

	desc = kzalloc_node(sizeof(*desc), GFP_KERNEL, node);

/* 학습 해설
 * Sparse mutex 획득: 외부 tree lock
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * irq_lock_sparse는 sparse_irq_lock mutex를 얻습니다. Maple Tree의 LOCK_EXTERN과 IRQ 할당·해제 및 sysfs 초기화 직렬화에 사용합니다. mutex 획득은 local IRQ 상태 저장이나 descriptor raw lock 획득과 같은 작업이 아닙니다. 허용된 sleep 문맥에서 짝 unlock과 함께 사용해야 합니다.
 * tree 전체 변경 보호와 개별 descriptor lock을 두 층으로 그립니다. IRQ hard 문맥에 임의 mutex를 추가하지 않고 실제 caller의 문맥을 따릅니다.
 */
void irq_lock_sparse(void)
{
	mutex_lock(&sparse_irq_lock);
}

void irq_unlock_sparse(void)
{
	mutex_unlock(&sparse_irq_lock);
}

static struct irq_desc *alloc_desc(int irq, int node, unsigned int flags,
				   const struct cpumask *affinity,
				   struct module *owner)
{
	struct irq_desc *desc;
	int ret;

	desc = kzalloc_node(sizeof(*desc), GFP_KERNEL, node);
	if (!desc)
		return NULL;

	ret = init_desc(desc, irq, node, flags, affinity, owner);
	if (unlikely(ret)) {
		kfree(desc);
		return NULL;
	}

/* 학습 해설
 * Sparse mutex 해제: 획득과 균형
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * irq_unlock_sparse는 같은 sparse_irq_lock mutex를 반환합니다. 보호된 tree 변경·sysfs 등록 등이 끝난 뒤 호출해야 하며 획득하지 않은 lock을 임의 해제하는 사용은 계약 밖입니다. descriptor의 raw spinlock이나 local IRQ 상태를 이 함수가 대신 복구하지 않습니다.
 * 성공·오류 경로마다 sparse lock과 unlock의 짝을 표시합니다. irq_sysfs_init의 base 실패 경로와 정상 순회 뒤 경로를 비교합니다.
 */
void irq_unlock_sparse(void)
{
	mutex_unlock(&sparse_irq_lock);
}

static struct irq_desc *alloc_desc(int irq, int node, unsigned int flags,
				   const struct cpumask *affinity,
				   struct module *owner)
{
	struct irq_desc *desc;
	int ret;

	desc = kzalloc_node(sizeof(*desc), GFP_KERNEL, node);
	if (!desc)
		return NULL;

	ret = init_desc(desc, irq, node, flags, affinity, owner);
	if (unlikely(ret)) {
		kfree(desc);
		return NULL;
	}

	return desc;
}

static void irq_kobj_release(struct kobject *kobj)

/* 학습 해설
 * Sparse descriptor 할당: NUMA와 초기화 실패
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * NUMA node에서 zero descriptor를 할당하고 실패면 NULL입니다. init_desc가 실패하면 descriptor를 kfree하고 NULL, 성공이면 pointer입니다. 초기화 함수는 자신이 얻은 masks·percpu 실패 자원을 정리하므로 이 wrapper는 바깥 객체를 담당합니다. 이 단계만으로 tree에 등록되지는 않습니다.
 * 객체 할당→내부 자원 초기화→caller tree 삽입의 세 단계를 그립니다. 내부 실패 정리와 바깥 객체 해제를 나눠 수명 누락을 확인합니다.
 */
static struct irq_desc *alloc_desc(int irq, int node, unsigned int flags,
				   const struct cpumask *affinity,
				   struct module *owner)
{
	struct irq_desc *desc;
	int ret;

	desc = kzalloc_node(sizeof(*desc), GFP_KERNEL, node);
	if (!desc)
		return NULL;

	ret = init_desc(desc, irq, node, flags, affinity, owner);
	if (unlikely(ret)) {
		kfree(desc);
		return NULL;
	}

	return desc;
}

static void irq_kobj_release(struct kobject *kobj)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);

	free_masks(desc);
	free_percpu(desc->kstat_irqs);

/* 학습 해설
 * Kobject 최종 release: 내부 자원과 객체
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * kobject에서 container_of로 descriptor를 찾고 masks, per-CPU statistics, descriptor 자체 순으로 해제합니다. kobj_type.release가 이 함수를 연결합니다. call_rcu callback의 kobject_put과 최종 release는 참조 수명에 따라 다른 시점일 수 있으며 이 함수가 tree 삭제까지 담당하지 않습니다.
 * tree 삭제→grace period→put→마지막 reference release 흐름을 그립니다. kobject 참조가 남아 있는 경우 실제 kfree가 더 늦을 수 있음을 표시합니다.
 */
static void irq_kobj_release(struct kobject *kobj)
{
	struct irq_desc *desc = container_of(kobj, struct irq_desc, kobj);

	free_masks(desc);
	free_percpu(desc->kstat_irqs);
	kfree(desc);
}

static void delayed_free_desc(struct rcu_head *rhp)
{
	struct irq_desc *desc = container_of(rhp, struct irq_desc, rcu);

	kobject_put(&desc->kobj);
}

static void free_desc(unsigned int irq)
{
	struct irq_desc *desc = irq_to_desc(irq);

	irq_remove_debugfs_entry(desc);
	unregister_irq_proc(irq, desc);

	/*
	 * sparse_irq_lock protects also show_interrupts() and
	 * kstat_irq_usr(). Once we deleted the descriptor from the
	 * sparse tree we can free it. Access in proc will fail to
	 * lookup the descriptor.
	 *
	 * The sysfs entry must be serialized against a concurrent
	 * irq_sysfs_init() as well.
	 */

/* 학습 해설
 * RCU 지연 callback: kobject put 위임
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * rcu_head에서 descriptor를 얻어 kobject_put을 호출합니다. 직접 kfree가 아닙니다. free_desc가 call_rcu를 예약한 뒤 grace period에 도달해 실행하는 callback이며 실제 마지막 kobject reference가 반환될 때 release로 정리됩니다. RCU와 reference 수명의 두 보호를 함께 읽어야 합니다.
 * reader가 끝난 뒤 put하고 다른 sysfs reference가 남았으면 최종 free가 더 늦는 그림을 그립니다. delay를 고정 밀리초 timer로 설명하지 않습니다.
 */
static void delayed_free_desc(struct rcu_head *rhp)
{
	struct irq_desc *desc = container_of(rhp, struct irq_desc, rcu);

	kobject_put(&desc->kobj);
}

static void free_desc(unsigned int irq)
{
	struct irq_desc *desc = irq_to_desc(irq);

	irq_remove_debugfs_entry(desc);
	unregister_irq_proc(irq, desc);

	/*
	 * sparse_irq_lock protects also show_interrupts() and
	 * kstat_irq_usr(). Once we deleted the descriptor from the
	 * sparse tree we can free it. Access in proc will fail to
	 * lookup the descriptor.
	 *
	 * The sysfs entry must be serialized against a concurrent
	 * irq_sysfs_init() as well.
	 */
	irq_sysfs_del(desc);
	delete_irq_desc(irq);

/* 학습 해설
 * Sparse descriptor free: 노출 제거 후 RCU
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * debugfs·proc 노출을 제거하고 sysfs를 지운 뒤 tree 번호를 삭제합니다. 이후 call_rcu로 delayed_free_desc를 예약합니다. sparse_irq_lock은 proc 통계 조회와 sysfs 초기화도 보호합니다. 반환 즉시 descriptor·masks·stats를 모두 kfree했다고 읽으면 안 됩니다. 유효 할당 IRQ가 선행 조건입니다.
 * 노출 제거·신규 조회 실패·기존 RCU reader·최종 release의 시간을 그립니다. 번호 free와 객체 메모리 free가 다른 시점인 이유를 문제로 풉니다.
 */
static void free_desc(unsigned int irq)
{
	struct irq_desc *desc = irq_to_desc(irq);

	irq_remove_debugfs_entry(desc);
	unregister_irq_proc(irq, desc);

	/*
	 * sparse_irq_lock protects also show_interrupts() and
	 * kstat_irq_usr(). Once we deleted the descriptor from the
	 * sparse tree we can free it. Access in proc will fail to
	 * lookup the descriptor.
	 *
	 * The sysfs entry must be serialized against a concurrent
	 * irq_sysfs_init() as well.
	 */
	irq_sysfs_del(desc);
	delete_irq_desc(irq);

	/*
	 * We free the descriptor, masks and stat fields via RCU. That
	 * allows demultiplex interrupts to do rcu based management of
	 * the child interrupts.
	 * This also allows us to use rcu in kstat_irqs_usr().
	 */
	call_rcu(&desc->rcu, delayed_free_desc);

/* 학습 해설
 * 연속 sparse 할당: affinity 검증과 역정리
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * affinity 배열이 있으면 모든 cnt mask가 비어 있지 않은지 먼저 확인합니다. 각 descriptor는 mask의 첫 CPU node에 할당하고 managed면 MANAGED·SHUTDOWN, 입력 affinity면 SET flag를 설정합니다. tree·sysfs·debugfs에 연결하며 중간 alloc 실패는 앞 descriptor를 역순 free하고 ENOMEM입니다. sysfs 경고와 tree 삽입 경고는 이 alloc 실패 branch와 다릅니다.
 * mask 배열 길이 cnt와 각 객체의 NUMA node 선택을 그립니다. 세 번째 객체 실패에서 앞 두 개가 역정리되는 경로와 RCU 지연 free를 연결합니다.
 */
static int alloc_descs(unsigned int start, unsigned int cnt, int node,
		       const struct irq_affinity_desc *affinity,
		       struct module *owner)
{
	struct irq_desc *desc;
	int i;

	/* Validate affinity mask(s) */
	if (affinity) {
		for (i = 0; i < cnt; i++) {
			if (cpumask_empty(&affinity[i].mask))
				return -EINVAL;
		}
	}

	for (i = 0; i < cnt; i++) {
		const struct cpumask *mask = NULL;
		unsigned int flags = 0;

		if (affinity) {
			if (affinity->is_managed) {
				flags = IRQD_AFFINITY_MANAGED |
					IRQD_MANAGED_SHUTDOWN;
			}
			flags |= IRQD_AFFINITY_SET;
			mask = &affinity->mask;

/* 학습 해설
 * Sparse 번호 상한 확장: 최대 한계
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SPARSE에서 요청 상한이 MAX_SPARSE_IRQS보다 크면 ENOMEM입니다. 범위 안이면 nr_irqs를 입력으로 갱신하고 0입니다. 이 함수 자체는 descriptor 객체를 할당하거나 tree에 저장하지 않습니다. 상한은 번호 공간의 관리 한계이고 사용 중 객체 수와 같은 값이 아닙니다.
 * nr_irqs 64에서 80으로 확장한 뒤 실제 cnt 객체 할당은 별도인 그림을 그립니다. MAX 경계 초과의 반환과 번호 공간의 상한 의미를 구별합니다.
 */
static int irq_expand_nr_irqs(unsigned int nr)
{
	if (nr > MAX_SPARSE_IRQS)
		return -ENOMEM;
	nr_irqs = nr;
	return 0;
}

int __init early_irq_init(void)
{
	int i, initcnt, node = first_online_node;
	struct irq_desc *desc;

	init_irq_default_affinity();

	/* Let arch update nr_irqs and return the nr of preallocated irqs */
	initcnt = arch_probe_nr_irqs();
	printk(KERN_INFO "NR_IRQS: %d, nr_irqs: %d, preallocated irqs: %d\n",
	       NR_IRQS, nr_irqs, initcnt);

	if (WARN_ON(nr_irqs > MAX_SPARSE_IRQS))
		nr_irqs = MAX_SPARSE_IRQS;

	if (WARN_ON(initcnt > MAX_SPARSE_IRQS))
		initcnt = MAX_SPARSE_IRQS;

/* 학습 해설
 * Sparse early IRQ: architecture 사전 번호
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * 기본 affinity를 준비하고 arch_probe_nr_irqs로 사전 할당 수와 architecture 번호 정책을 얻습니다. nr_irqs·initcnt가 MAX를 넘으면 경고 후 제한하고 initcnt가 더 크면 nr_irqs를 올립니다. 각 번호를 alloc_desc 후 삽입하며 이 loop는 alloc_desc NULL을 독립 검사하지 않습니다. 마지막 arch_early_irq_init 결과를 반환합니다.
 * architecture 초기 번호 공간·preallocated 수·동적 확장을 나눠 그립니다. 이 early 경로의 할당 전제와 정상 동적 alloc 실패 정리를 같은 것으로 가정하지 않습니다.
 */
int __init early_irq_init(void)
{
	int i, initcnt, node = first_online_node;
	struct irq_desc *desc;

	init_irq_default_affinity();

	/* Let arch update nr_irqs and return the nr of preallocated irqs */
	initcnt = arch_probe_nr_irqs();
	printk(KERN_INFO "NR_IRQS: %d, nr_irqs: %d, preallocated irqs: %d\n",
	       NR_IRQS, nr_irqs, initcnt);

	if (WARN_ON(nr_irqs > MAX_SPARSE_IRQS))
		nr_irqs = MAX_SPARSE_IRQS;

	if (WARN_ON(initcnt > MAX_SPARSE_IRQS))
		initcnt = MAX_SPARSE_IRQS;

	if (initcnt > nr_irqs)
		nr_irqs = initcnt;

	for (i = 0; i < initcnt; i++) {
		desc = alloc_desc(i, node, 0, NULL, NULL);
		irq_insert_desc(i, desc);
	}
	return arch_early_irq_init();

/* 학습 해설
 * 고정 배열 early IRQ: 전부 초기화와 오류 prefix 정리
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SPARSE off는 cacheline 정렬의 irq_desc[NR_IRQS] 배열을 사용하며 GNU range initializer로 기본 bad handler·depth·lock을 넣습니다. early init은 배열의 모든 객체에 init_desc를 호출합니다. i에서 실패면 앞 prefix의 masks·percpu를 해제하고 오류를 반환합니다. 배열 객체 자체는 동적 kfree하지 않습니다.
 * 고정 배열과 sparse 동적 객체의 저장 방식 차이를 그립니다. 초기화 실패 prefix를 역으로 정리하고 배열 storage가 유지되는 수명을 표시합니다.
 */
int __init early_irq_init(void)
{
	int count, i, node = first_online_node;
	int ret;

	init_irq_default_affinity();

	printk(KERN_INFO "NR_IRQS: %d\n", NR_IRQS);

	count = ARRAY_SIZE(irq_desc);

	for (i = 0; i < count; i++) {
		ret = init_desc(irq_desc + i, i, node, 0, NULL, NULL);
		if (unlikely(ret))
			goto __free_desc_res;
	}

	return arch_early_irq_init();

__free_desc_res:
	while (--i >= 0) {
		free_masks(irq_desc + i);
		free_percpu(irq_desc[i].kstat_irqs);
	}

	return ret;

/* 학습 해설
 * 고정 배열 IRQ 조회: 번호 경계
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SPARSE off irq_to_desc는 irq < NR_IRQS이면 irq_desc+irq, 아니면 NULL입니다. 이 주소의 객체 storage 존재와 해당 번호가 현재 allocated tree에 등록됐는지는 다른 정보입니다. 고정 배열 조회를 sparse tree lookup과 동일한 할당 존재 검사로 일반화하면 안 됩니다.
 * 번호 0·NR_IRQS-1·NR_IRQS의 pointer를 풉니다. 배열 범위와 tree allocated 목록을 두 축으로 그려 조회 의미의 구성별 차이를 읽습니다.
 */
struct irq_desc *irq_to_desc(unsigned int irq)
{
	return (irq < NR_IRQS) ? irq_desc + irq : NULL;
}
EXPORT_SYMBOL(irq_to_desc);

static void free_desc(unsigned int irq)
{
	struct irq_desc *desc = irq_to_desc(irq);
	unsigned long flags;

	raw_spin_lock_irqsave(&desc->lock, flags);
	desc_set_defaults(irq, desc, irq_desc_get_node(desc), NULL, NULL);
	raw_spin_unlock_irqrestore(&desc->lock, flags);
	delete_irq_desc(irq);
}

