			      const struct irq_affinity_desc *affinity,
			      struct module *owner)
{
	u32 i;

	for (i = 0; i < cnt; i++) {
		struct irq_desc *desc = irq_to_desc(start + i);

/* 학습 해설
 * 고정 배열 free: 기본 상태 재설정
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SPARSE off는 descriptor raw irqsave lock 안에서 desc_set_defaults로 상태·통계·owner 등을 초기값으로 돌립니다. unlock 뒤 allocated tree 번호를 삭제합니다. 동적 sparse 경로처럼 객체 자체를 RCU/kfree하지 않으며 기존 masks·percpu storage를 재사용합니다. 유효 IRQ가 caller 조건입니다.
 * free 뒤 같은 배열 주소를 유지하면서 상태가 초기화되는 그림을 그립니다. sparse free와 비교해 storage 수명·tree 연결 수명·통계 reset의 차이를 표시합니다.
