	unsigned long flags;

	raw_spin_lock_irqsave(&desc->lock, flags);
	desc_set_defaults(irq, desc, irq_desc_get_node(desc), NULL, NULL);
	raw_spin_unlock_irqrestore(&desc->lock, flags);
	delete_irq_desc(irq);
}

static inline int alloc_descs(unsigned int start, unsigned int cnt, int node,
			      const struct irq_affinity_desc *affinity,
			      struct module *owner)
{
	u32 i;

	for (i = 0; i < cnt; i++) {
		struct irq_desc *desc = irq_to_desc(start + i);

		desc->owner = owner;
		irq_insert_desc(start + i, desc);
	}
	return start;
}

/* 학습 해설
 * 고정 배열 alloc: owner와 tree 연결
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * SPARSE off는 범위의 배열 descriptor를 조회해 owner를 설정하고 tree에 삽입합니다. sparse처럼 각 mask를 검증하거나 새 객체를 할당하는 본문이 아닙니다. start를 반환하며 상위 범위 allocator가 유효 번호 구간을 준비해야 합니다. affinity 인자는 이 구현에서 사용하지 않습니다.
 * 같은 API가 구성에 따라 다른 storage 전략을 사용하는 예를 풉니다. 입력 affinity가 있다고 이 branch가 새 mask를 복사한다고 가정하지 않습니다.
 */
static inline int alloc_descs(unsigned int start, unsigned int cnt, int node,
			      const struct irq_affinity_desc *affinity,
			      struct module *owner)
{
	u32 i;

	for (i = 0; i < cnt; i++) {
		struct irq_desc *desc = irq_to_desc(start + i);

		desc->owner = owner;
		irq_insert_desc(start + i, desc);
	}
	return start;
}

