/**
 * irq_free_descs - free irq descriptors
 * @from:	Start of descriptor range
 * @cnt:	Number of consecutive irqs to free
 */
void irq_free_descs(unsigned int from, unsigned int cnt)
{
	int i;

	if (from >= nr_irqs || (from + cnt) > nr_irqs)
		return;

	mutex_lock(&sparse_irq_lock);
	for (i = 0; i < cnt; i++)
		free_desc(from + i);

	mutex_unlock(&sparse_irq_lock);

/* 학습 해설
 * IRQ 범위 free: 경계와 할당 존재 계약
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * from이 nr_irqs 이상이거나 from+cnt가 nr_irqs를 넘으면 반환합니다. sparse mutex 아래 cnt개 free_desc를 호출하고 unlock합니다. unsigned 덧셈의 모든 overflow를 따로 검사하는 본문은 아니며 각 번호의 유효 할당 존재도 caller 조건입니다. 범위 검사만으로 빈 번호 free의 안전성을 증명하지 않습니다.
 * 작고 유효한 연속 할당 범위를 해제하는 예를 풉니다. 상한 검사·할당 존재·덧셈 범위를 서로 다른 조건으로 표시합니다.
 */
void irq_free_descs(unsigned int from, unsigned int cnt)
{
	int i;

	if (from >= nr_irqs || (from + cnt) > nr_irqs)
		return;

	mutex_lock(&sparse_irq_lock);
	for (i = 0; i < cnt; i++)
		free_desc(from + i);

	mutex_unlock(&sparse_irq_lock);
}
EXPORT_SYMBOL_GPL(irq_free_descs);

