 * 일반·percpu descriptor와 요구 check의 네 조합을 풉니다. bus lock→desc lock의 순서와 실패 반환에서 pointer/flags 의미를 표시합니다.
 */
__irq_get_desc_lock(unsigned int irq, unsigned long *flags, bool bus,
		    unsigned int check)
{
	struct irq_desc *desc = irq_to_desc(irq);

	if (desc) {
		if (check & _IRQ_DESC_CHECK) {
			if ((check & _IRQ_DESC_PERCPU) &&
			    !irq_settings_is_per_cpu_devid(desc))
				return NULL;

			if (!(check & _IRQ_DESC_PERCPU) &&
			    irq_settings_is_per_cpu_devid(desc))
				return NULL;
		}

		if (bus)
			chip_bus_lock(desc);
		raw_spin_lock_irqsave(&desc->lock, *flags);
	}
	return desc;
}

void __irq_put_desc_unlock(struct irq_desc *desc, unsigned long flags, bool bus)
	__releases(&desc->lock)
{

/* 학습 해설
 * Descriptor unlock: 반대 순서와 flags 복원
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * 먼저 raw_spin_unlock_irqrestore로 descriptor와 이전 local 상태를 복원합니다. bus=true이면 뒤 chip_bus_sync_unlock합니다. __releases annotation은 분석 도구에 잠금 해제를 표현하며 runtime의 실제 unlock은 본문 호출입니다. 유효하고 잠긴 descriptor가 선행 조건입니다.
 * 획득 bus→desc와 해제 desc→bus를 나란히 그립니다. flags는 대응 획득에서 얻은 값이어야 하며 임의 숫자 복원을 정상 사용으로 만들지 않습니다.
 */
void __irq_put_desc_unlock(struct irq_desc *desc, unsigned long flags, bool bus)
	__releases(&desc->lock)
{
	raw_spin_unlock_irqrestore(&desc->lock, flags);
	if (bus)
		chip_bus_sync_unlock(desc);
}

int irq_set_percpu_devid_partition(unsigned int irq,
				   const struct cpumask *affinity)
{
	struct irq_desc *desc = irq_to_desc(irq);

	if (!desc || desc->percpu_enabled)
		return -EINVAL;

	desc->percpu_enabled = kzalloc(sizeof(*desc->percpu_enabled), GFP_KERNEL);

	if (!desc->percpu_enabled)
		return -ENOMEM;

	desc->percpu_affinity = affinity ? : cpu_possible_mask;

	irq_set_percpu_devid_flags(irq);
