/**
 * kstat_irqs_usr - Get the statistics for an interrupt from thread context
 * @irq:	The interrupt number
 *
 * Returns the sum of interrupt counts on all cpus since boot for @irq.
 *
 * It uses rcu to protect the access since a concurrent removal of an
 * interrupt descriptor is observing an rcu grace period before
 * delayed_free_desc()/irq_kobj_release().
 */
unsigned int kstat_irqs_usr(unsigned int irq)
{
	unsigned int sum;

	rcu_read_lock();

/* 학습 해설
 * Thread 통계 조회: RCU 객체 수명 보호
 * IRQ 번호 저장소·연속 범위 할당·CPU mask와 per-CPU 통계·잠금/RCU/kobject 수명·sysfs·dispatch 문맥의 원리와 적용 조건을 실제 구현으로 공부합니다.
 * rcu_read_lock 안에서 kstat_irqs를 호출하고 unlock 후 합계를 반환합니다. concurrent removal이 tree 삭제 뒤 grace period를 관찰하므로 통계 객체 수명을 보호합니다. RCU가 통계 값을 모두 같은 순간으로 고정하거나 writer를 전부 막는 것은 아닙니다. reader 수명과 값 일관성을 구분합니다.
 * 기존 reader→tree 삭제→reader 종료→지연 release의 그림을 그립니다. 메모리 안전 수명 보호와 approximate 통계 관찰의 다른 의미를 풉니다.
 */
unsigned int kstat_irqs_usr(unsigned int irq)
{
	unsigned int sum;

	rcu_read_lock();
	sum = kstat_irqs(irq);
	rcu_read_unlock();
	return sum;
}

